# Parse the data we got
# sqlite3 default output is pipe-separated

def parse_sqlite_rows(output, headers=None):
    """Parse sqlite3 CLI output into list of dicts"""
    if not output or output == '(command completed with no output)':
        return []
    lines = [l.strip() for l in output.strip().split('\n') if l.strip()]
    if not lines:
        return []
    if headers:
        return [dict(zip(headers, line.split('|'))) for line in lines]
    return [line.split('|') for line in lines]

